{
 "path": "/home/ubuntu/continual-arc-baselines/.workbench/runs/adhoc-openclawlearner-1792544556/attempts/3223be82bb504fb6b3585b3b468eaac7/system/state/workspace/programs/task-e725ee21.py",
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Extract horizontal stripe colors; repeat the ordered motif as diagonal bands.
    colors = []
    for row in grid:
        vals = [x for x in row if x]
        if vals and (not colors or colors[-1] != vals[0]):
            colors.append(vals[0])
    if not colors:
        return [row[:] for row in grid]
    return [[colors[(c-r) % len(colors)] for c in range(w)] for r in range(h)]
"
}

